<template><view class="page"><DevNotice/><view class="hero"><view class="hero-copy"><text class="eyebrow">智能车险服务 —</text><view class="headline"><text>投保</text>更简单</view><text class="sub">对话引导，轻松整理资料</text><view class="cta" @tap="household">了解服务　→</view></view><image src="/insurance/static/car.png" mode="aspectFit"/><view class="dots">●　•　•</view></view><view class="grid"><view v-for="c in cards" :key="c.key" class="card" @tap="enter(c)"><image :src="'/insurance/static/'+c.img+'.png'" mode="aspectFit"/><text class="card-title">{{c.title}}</text><text class="card-sub">{{c.sub}}</text><text class="arrow">›</text></view></view><view class="foot">仅接入泰康渠道 · 具体方案以实际返回为准</view></view></template>
<script>
import DevNotice from '../components/DevNotice.vue';
import { insuranceConfig } from '../lib/config.js';
export default {components:{DevNotice},data(){return {cards:[{key:'household',img:'car',title:'家用车入口',sub:'引导式对话办理'},{key:'compulsory',img:'shield',title:'交强险入口',sub:'按需核对保障'},{key:'truck',img:'truck',title:'货车入口',sub:'收集投保资料'},{key:'motorcycle',img:'moto',title:'摩托车入口',sub:'收集投保资料'},{key:'history',img:'clipboard',title:'报价记录',sub:'查看会话与资料'},{key:'help',img:'robot',title:'人工客服',sub:'返回原商城咨询'}]};},methods:{household(){uni.navigateTo({url:'/insurance/pages/household'});},enter(c){if(c.key==='household')return this.household();if(c.key==='history')return uni.navigateTo({url:'/insurance/pages/history'});if(c.key==='help'){try{const f=insuranceConfig().openCustomerService;if(f)return f();}catch{}return uni.showToast({title:'请使用原商城客服入口',icon:'none'});}uni.navigateTo({url:'/insurance/pages/chat?mode='+c.key});}}};
</script>
