.page{background:#fdf7ee;min-height:100vh;padding:26rpx 24rpx;box-sizing:border-box;color:#241c16}.hero{height:390rpx;background:linear-gradient(120deg,#fff0d9,#fff8ed);border-radius:34rpx;position:relative;overflow:hidden;padding:35rpx;box-sizing:border-box}.hero-copy{position:relative;z-index:1}.eyebrow{color:#ff741c;font-size:27rpx}.headline{font-size:65rpx;font-weight:800;margin:16rpx 0 18rpx;letter-spacing:-3rpx}.headline text{color:#ff6b16}.sub{color:#777;font-size:30rpx;display:block}.cta{margin-top:24rpx;display:inline-block;background:linear-gradient(90deg,#ff842c,#ff6117);color:#fff;padding:18rpx 30rpx;border-radius:45rpx;font-size:29rpx;font-weight:700}.hero image{position:absolute;width:345rpx;height:240rpx;right:-30rpx;bottom:9rpx}.dots{position:absolute;bottom:15rpx;left:39rpx;color:#fb8a3a;font-size:21rpx}.grid{display:grid;grid-template-columns:1fr 1fr;gap:19rpx;margin-top:24rpx}.card{border-radius:30rpx;background:#fff;padding:18rpx 28rpx 34rpx;position:relative;min-width:0}.card image{width:100%;height:180rpx}.card-title{display:block;font-size:32rpx;font-weight:700;margin-bottom:8rpx}.card-sub{display:block;color:#8b8985;font-size:25rpx}.arrow{position:absolute;right:25rpx;bottom:51rpx;font-size:42rpx;color:#999}.foot{text-align:center;font-size:22rpx;color:#ac9e8d;line-height:1.7;margin:30rpx 0;padding-bottom:env(safe-area-inset-bottom)}
